<div class="result-line"><span><?= number_format($state['total']) ?> <?= $state['q'] || $state['category'] || $state['software'] || $state['artist']!=='' ? 'matching images' : 'images in the gallery' ?></span><span>Page <?= number_format($state['page']) ?> / <?= number_format($state['pages']) ?></span></div>
<?php if (!$state['items']): ?><div class="empty-state"><h2>No artworks found.</h2><p>Try another search or category.</p><a href="/">Clear filters →</a></div><?php else: ?>
<div class="art-grid"><?php foreach($state['items'] as $i=>$item): ?><a class="art-card" href="/art/<?= (int)$item['id'] ?>"><span class="software-card-label" data-software="<?= e(isset(SOFTWARE[$item['software']??'bryce']) ? ($item['software']??'bryce') : 'other') ?>"><?= e(SOFTWARE[$item['software']??'bryce']??'Other software') ?></span><div class="art-image-wrap"><img class="art-image" src="<?= e(media_url($item)) ?>" alt="<?= e($item['title']) ?>" loading="<?= $i<3 ? 'eager' : 'lazy' ?>" decoding="async"><span class="art-open" aria-hidden="true">↗</span></div><div class="art-meta"><div><p class="art-category"><?= e(category_name($data,$item)) ?></p><h3><?= e($item['title']) ?></h3></div><span class="art-author"><?= e($item['author']?:'Community artist') ?></span></div><div class="card-stats"><span><?= e(substr($item['date']??'Archive',0,10)) ?></span><span><?= number_format((int)($item['views']??0)) ?> unique views</span></div></a><?php endforeach; ?></div>
<?php endif; ?>
<?php if ($state['pages']>1): ?><nav class="pagination" aria-label="Gallery pages"><div class="page-links"><?php foreach([['First',1],['−10',$state['page']-10,'Back 10 pages'],['−5',$state['page']-5,'Back 5 pages'],['← Previous',$state['page']-1],['Next →',$state['page']+1],['+5',$state['page']+5,'Forward 5 pages'],['+10',$state['page']+10,'Forward 10 pages'],['Last',$state['pages']]] as $jump): $target=max(1,min($state['pages'],$jump[1])); ?><?php if ($target===$state['page']): ?><span class="page-disabled" aria-disabled="true"><?= e($jump[0]) ?></span><?php else: ?><a href="<?= e(gallery_url($state,['page'=>$target])) ?>" aria-label="<?= e($jump[2]??$jump[0]) ?>"><?= e($jump[0]) ?></a><?php endif; ?><?php endforeach; ?></div>
<form class="page-jump" action="/#gallery" method="get"><?php foreach(['q','category','software','artist','sort','perPage'] as $key): ?><input type="hidden" name="<?= $key ?>" value="<?= e($state[$key]) ?>"><?php endforeach; ?><label for="gallery-page">Page</label><input id="gallery-page" name="page" type="number" min="1" max="<?= $state['pages'] ?>" value="<?= $state['page'] ?>" required><span>of <?= number_format($state['pages']) ?></span><button type="submit">Go</button></form></nav><?php endif; ?>
<p class="help">* Historical archive counts are shown separately on artwork pages. New unique views use account/browser deduplication.</p>
